WITH payload AS (SELECT $archive_payload$[{"id":"b81de361-50e1-588e-8d26-e63948890968","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وللعقم، والع نة -املصادقة على العقم -عقم الزوج عي ب يثبت به اخليار للزوجة -فسخ النكاح دون عوض بسبب عقم الزوج .","document_number":"33455749","case_number":"33474935","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/16","year":"1434","subject":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وللعقم، والع نة -املصادقة على العقم -عقم الزوج عي ب يثبت به اخليار للزوجة -فسخ النكاح دون عوض بسبب عقم الزوج .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/16 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33455749 :‬‬\n                    ‫َر ْق ُم الدعوى‪33474935 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34221660‬تاريخه‪1434/5/25:‬هـ‬\n\n\n ‫فســخ نــكاح ‪ -‬طلــب فســخ النــكاح بعــد الدخــول لســوء العشــرة‪ ،‬وللعقــم‪،‬‬\n ‫والعِ َّنــة ‪ -‬املصادقــة علــى العقــم ‪ -‬عقــم الــزوج عيـ ٌـب يثبــت بــه اخليــار‬\n                  ‫للزوجــة ‪ -‬فســخ النــكاح دون عــوض بســبب عقــم الــزوج ‪.‬‬\n\n\n\n\n                                                        ‫ٍ‬\n ‫كاف يف فســخ النــكاح‪ ،‬وهــو مــروي عــن أميــر املؤمنــن‬     ‫‪ .1‬العقــم عيــب‬\n ‫عمــر بــن اخلطــاب رضــي اهلل عنــه‪ ،‬واختيــار شــيخ اإلســام ابــن تيميــة‬\n ‫كمــا يف االختيــارات (‪ )222‬وتلميــذه ابــن القيــم كمــا يف زاد املعــاد‬\n                                                                     ‫(‪.)181/5‬‬\n ‫‪ .2‬قال ســماحة الشــيخ محمد بن إبراهيم كما يف مجموع الفتاوى‬\n ‫(‪( )165/10‬فالعقــم وهــو عــدم الــوالدة ال ريــب أن الصحيــح فيــه أنــه‬\n ‫عيــب فــإن مــن أهــم وأعظــم مقاصــد املــرأة مــن النــكاح حتصيــل الولــد )‬\n                                                                            ‫أ‪.‬هـ‬\n\n\n\n\n ‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا أن املدعــى عليــه تزوجهــا‬\n ‫بواليــة والدهــا مبهــر قــدره عشــرون ألــف ريــال اســتلمته كامـاً‪ ،‬وأنــه‬\n ‫دخــل بهــا ‪ ،‬ولــم تــرزق منــه بــأوالد‪ ،‬وأن العشــرة ســاءت بينهمــا‪ ،‬وأنــه‬\n ‫تركهــا عنــد أهلهــا‪ ،‬كمــا أنــه عقيــم ‪ ،‬وعنــن وغيــر قادر علــى اجلماع‪،‬‬\n\n                                                                                        ‫‪356‬‬\n\f      ‫وأنهــا ترغــب يف األوالد والذريــة وطلبــت فســخ نكاحهــا منــه ‪ ،‬بعــرض‬\n      ‫الدعــوى علــى املدعــى عليــه صــادق علــى الــزواج واملهــر‪ ،‬وقــرر أنهــا هــي‬\n      ‫التــي رفضــت العــودة إلــى بيــت الزوجيــة ‪ ،‬كمــا صــادق علــى مــا ادعتــه‬\n      ‫مــن العقــم وقــرر أنــه لــم يعلــم بذلــك إال بعــد ســنتني مــن زواجــه باملدعيــة‬\n      ‫‪ ،‬وأنكــر مــا ادعتــه مــن العنــة ‪ ،‬ولــم يوافــق علــى طلبهــا الفســخ ‪ ،‬وقــرر‬\n      ‫أنــه يحبهــا حبــا شــديدا ‪ ،‬جــرى محاولــة اإلصــاح بــن الطرفــن فلــم‬\n      ‫يصطلحــا ‪ ،‬إقــرار املدعــى عليــه أنــه عقيــم ال يولــد لــه ‪ ،‬واملــرء مؤاخــذ‬\n      ‫بإقــراره ‪ ،‬مــا تقــرر شــرعا مــن أن العقــم عيــب يثبــت بــه اخليــار للمــرأة‬\n      ‫‪ ،‬وهــو عيــب كاف يف فســخ النــكاح ‪ ،‬لــذا مت احلكــم بفســخ نــكاح‬\n      ‫املدعيــة مــن زوجهــا املدعــى عليــه بــا عــوض ‪ ،‬جــرى إفهــام املدعيــة‬\n      ‫بــأن عليهــا العــدة الشــرعية ابتــداء مــن تاريــخ احلكــم حيــث ذكــرت‬\n      ‫أنهــا مــن ذوات األقــراء ‪ ،‬وأن عليهــا أال تتــزوج أو تتعــرض خلاطــب‬\n      ‫حتــى يكتســب احلكــم القطعيــة‪ ،‬كمــا جــرى إفهــام املدعــى عليــه‬\n      ‫بــأن املدعيــة قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر‬\n      ‫جديديــن‪ ،‬وأن عليــه مراجعــة األحــوال املدنيــة لتســجيل الواقعــة وإنــزال‬\n      ‫اســم املــرأة مــن دفتــر العائلــة بعــد اكتســاب احلكــم القطعيــة ‪ ،‬بعــرض‬\n      ‫احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة وطلــب التمييــز وجــرى إفهامــه بتعليمــات االعتــراض ‪ ،‬تقــدم‬\n      ‫املدعــى عليــه بالئحتــه االعتراضيــة املكونــة مــن أربــع صفحــات وطلــب‬\n      ‫فيهــا مخاطبــة املستشــفى لإلفــادة عــن حالتــه إذا كان هنــاك أمــل يف‬\n      ‫شــفائه ‪ ،‬جــرت مخاطبــة املستشــفى فــورد اجلــواب املتضمــن اإلفــادة‬\n      ‫باآلتــي‪ -1 :‬متالزمــة (كلينيفيلتــر) حالــة دائمــة ال شــفاء منهــا وقــد مت‬\n      ‫األخــذ بجميــع األســباب املعروفــة طبيــا حملاولــة املســاعدة يف حــدوث‬\n\n\n‫‪357‬‬\n\f‫حمــل وإجنــاب إال أنهــا لــم تنجــح ‪ -2 .‬الــدواء الــذي يتناولــه املريض حاليا‬\n‫ليــس لعــاج صعوبــة اإلجنــاب وإمنــا لتحســن جوانــب صحيــة أخــرى لــدى‬\n‫املريــض) ‪ ،‬لــم يجــد ناظــر القضيــة يف الالئحــة االعتراضيــة مــا يؤثــر‬\n‫علــى احلكــم ‪ ،‬مت رفــع املعاملــة حملكمــة االســتئناف ‪ ،‬ورد احلكــم مــن‬\n                                           ‫محكمــة االســتئناف مصدق ـ ًا ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ )........‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة‬\n‫(‪ )........‬املســاعد برقــم ‪ 33474935‬وتاريــخ ‪1433/7/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331358768‬وتاريــخ ‪1433/07/20‬ه ـ حضــرت‬\n‫(‪ )........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬املعــرف‬\n‫بهــا مــن قبــل والدهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم …‪ .‬وحضــر حلضورهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )........‬فادعــت (‪ )........‬قائلــة يف دعواهــا إن املدعــى‬\n‫عليــه زوجــي تزوجنــي بواليــة والــدي مبوجــب عقــد النــكاح رقــم ‪.......‬‬\n‫يف ‪1429/03/12‬ه ـ الصــادر مــن احملكمــة العامــة مبكــة املكرمــة‬\n‫وأمهرنــي مبلغــا وقــدره عشــرون ألــف ريــال اســتلمته كامــا ودخــل بــي‬\n‫الدخــول الشــرعي ولــم أرزق منــه بــأوالد وقــد ســاءت العشــرة بينــي وبينــه‬\n‫فهــو يخاصمنــي ويهيننــي أمــام النــاس وبتاريــخ ‪1432/6/7‬ه ـ خرجــت‬\n‫مــع املدعــى عليــه مــن بيتنــا يف محافظــة جــدة واوصلنــي إلــى عملــي يف‬\n‫‪ ..........‬يف محافظــة الطائــف ومكــث معــي أســبوعا ‪ -‬والعــادة أنــه يقــوم‬\n\n                                                                                    ‫‪358‬‬\n\f      ‫بإيصالــي ثــم يعــود إلــى عملــة يف محافظــة جــدة وأجلــس أنــا لوحــدي يف‬\n      ‫محافظــة الطائــف ثــم يعــود ألخــذي يف نهايــة األســبوع ‪ -‬ثــم رجــع إلــى‬\n      ‫محافظــة جــدة ‪ -‬كالعــادة ‪ -‬ويف نهايــة األســبوع طلبــت منــه العــودة إلــى‬\n      ‫محافظــة الطائــف كــي يوصلنــي ألهلــي إال أنــه رفــض فأتــى بــي والــدي‬\n      ‫ومكثــت يف بيــت أهلــي ثــم طلبــت مــن املدعــى عليــه أن أعــود لبيتــه‬\n      ‫فرفــض وتركنــي عنــد أهلــي طــوال هــذي الفتــرة ثــم إن املدعــى عليــه‬\n      ‫عقيــم وعنــن وغيــر قــادر علــى اجلمــاع وأنــا أرغــب يف األوالد والذريــة لــذا‬\n      ‫أطلــب فســخ نكاحــي منــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه قــال مــا ذكرتــه املدعيــة يف دعواهــا مــن الــزواج والعقــد واملهــر‬\n      ‫فهــو صحيــح ومــا ذكرتــه مــن حادثــة الطائــف فهــو صحيــح ولكنــي‬\n      ‫اتفقــت مــع والدهــا علــى أن يقــوم هــو بإعادتهــا مــن محافظــة الطائــف‬\n      ‫إلــى محافظــة جــدة وملــا عــادت مــع والدهــا إلــى محافظــة جــدة رفضــت‬\n      ‫العــودة معــي وأمــا مــا ذكرتــه مــن أنــي عقيــم ال يولــد لــي فهــو صحيــح‬\n      ‫وقــد علمــت بذلــك بعــد ســنتني مــن زواجــي باملدعيــة واحلمــد هلل علــى‬\n      ‫قضائــه وقــدره وأمــا العنــة فإننــي لســت عنينــا وأســتطيع اجلمــاع بصــورة‬\n      ‫طبيعيــة وأمــا طلبهــا فســخ النــكاح فــا أوافــق عليــه وأنــا أحبهــا حبــا‬\n      ‫شــديدا هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة جــرى منــي‬\n      ‫محاولــة االصــاح بــن الطرفــن فلــم يصطلحــا ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان واملعــرف ثــم جــرى منــي محاولــة االصــاح بــن الطرفــن فلــم‬\n      ‫يصطلحــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى‬\n      ‫عليــه بأنــه عقيــم ال يولــد لــه وألن اإلقــرار ســيد االدلــة واملــرء مؤاخــذ‬\n      ‫بإقــراره وملــا تقــرر شــرعا مــن أن العقــم عيــب يثبــت بــه اخليــار للمــرأة‬\n      ‫وهــو اختيــار شــيخ االســام ابــن تيميــة كمــا يف االختيــارات ص(‪)222‬‬\n\n\n‫‪359‬‬\n\f‫وتلميــذه ابــن القيــم كمــا يف زاد املعــاد (‪ )181/5‬وهــو مــروي عــن أميــر‬\n‫املؤمنــن عمــر بــن اخلطــاب رضــي اهلل عنــه وقــال ســماحة الشــيخ‬\n‫محمــد بــن إبراهيــم كمــا يف مجمــوع فتــاواه (‪« )165/10‬فالعقــم‬\n‫وهــو عــدم الــوالدة ال ريــب أن الصحيــح فيــه أنــه عيــب فــإن مــن أهــم‬\n‫وأعظــم مقاصــد املــرأة مــن النــكاح حتصيــل الولــد ) أ ‪ .‬ه ـ ونظــرا‬\n‫ألن العقــم ‪ ،‬واحلالــة هــذه ‪ ،‬عيــب كاف يف فســخ النــكاح لــذا كلــه‬\n‫فقــد فســخت نــكاح املدعيــة ‪ ..................‬مــن زوجهــا املدعــى عليــه‬\n‫‪ ..............‬بــا عــوض وبــه حكمــت وجــرى إفهــام املدعيــة بــأن عليهــا‬\n‫العــدة الشــرعية وهــي ثــاث حيــض ابتــداء مــن اليــوم فقــد ذكــرت‬\n‫أنهــا مــن ذوات األقــراء وأن عليهــا أال تتــزوج أو تتعــرض خلاطــب حتــى‬\n‫يكتســب احلكــم القطعية‪........‬يتبــع كمــا جــرى إفهــام املدعــى عليــه‬\n‫بــأن املدعيــة قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر‬\n‫جديديــن وأن عليــه مراجعــة األحــوال املدنيــة لتســجيل الواقعــة وإنــزال‬\n‫اســم املــرأة مــن دفتــر العائلــة بعــد اكتســاب احلكــم القطعيــة وبعــرض‬\n‫احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى عليــه‬\n‫عــدم القناعــة وطلــب التمييــز وجــرى إفهامــه بتعليمــات االعتــراض واهلل‬\n‫املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                           ‫يف ‪1433/11/15‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n‫يــوم األربعــاء املوافــق ‪1434/04/17‬ه ـ افتتحــت اجللســة بعــد أن تقــدم‬\n‫إلينــا املدعــى عليــه وكالــة ‪ .........‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ..........‬بالوكالــة عــن ‪ .........‬مبوجــب الوكالــة رقــم ‪ 65966‬يف‬\n‫‪1433/07/27‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة بشــمال محافظــة‬\n\n\n                                                                                    ‫‪360‬‬\n\f      ‫جــدة بالئحتــه االعتراضيــة املكونــة مــن أربــع صفحــات املقيــدة يف هــذه‬\n      ‫احملكمــة برقــم ‪ 33/2148553‬يف ‪1433/11/29‬ه ـ إذ أشــار فيهــا‬\n      ‫إلــى مخاطبــة ‪ ..........‬مبحافظــة جــدة لإلفــادة عــن حالــة موكلــه إذا‬\n      ‫كان هنــاك أمــل يف شــفائه فجــرت منــا مخاطبــة املستشــفى املذكــور‬\n      ‫مبوجــب خطابنــا رقــم ‪ 34486567‬يف ‪1433/3/‬ه ـ فوردنــا خطــاب‬\n      ‫مديــر إدارة خدمــات املرضــى باملستشــفى املذكــور رقــم ‪/33‬ج‪786/‬‬\n      ‫يف ‪1434/04/02‬ه ـ ونــص احلاجــة منــه (عليــه نفيــد فضيلتكــم باآلتــي‪:‬‬\n      ‫‪ -1‬متالزمــة (كلينيفيلتــر) حالــة دائمــة ال شــفاء منهــا وقــد مت األخــذ‬\n      ‫بجميــع األســباب املعروفــة طبيــا حملاولــة املســاعدة يف حــدوث حمــل‬\n                                                       ‫وإجنــاب إال أنهــا لــم تنجــح ‪.‬‬\n      ‫‪ - 2‬الــدواء الــذي يتناولــه املريــض حاليــا ليــس لعــاج صعوبــة اإلجنــاب‬\n      ‫وإمنــا لتحســن جوانــب صحيــة أخــرى لــدى املريــض )‪ .‬عليــه ونظــرا‬\n      ‫ملــا قــرره املستشــفى ‪ ،‬الــذي طالــب املدعــى عليــه مبخاطبتــه ‪ ،‬مــن‬\n      ‫أن املــرض املصــاب بــه املريــض ال شــفاء منــه وأنــه مت األخــذ بجميــع‬\n      ‫األســباب املعروفــة طبيــا حملاولــة املســاعدة يف حــدوث حمــل وإجنــاب‬\n      ‫وأنهــا لــم تنجــح وملــا جــاء يف أســباب احلكــم فــا زلــت علــى مــا حكمــت‬\n      ‫بــه كمــا لــم أجــد يف الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه مــا‬\n      ‫يؤثــر علــى احلكــم وقــررت بعــث املعاملــة حملكمــة االســتئناف حســب‬\n      ‫النظــام وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n      ‫‪1434/04/17‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n      ‫بعــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/06/14‬ه ـ افتتحــت اجللســة‬\n      ‫بعــد أن عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n      ‫‪ 34221660‬وتاريــخ ‪1434/05/25‬ه ـ ونــص احلاجــة منــه (وبدراســة‬\n\n\n‫‪361‬‬\n\f‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم) قاضــي اســتئناف ‪ ........‬ختــم وتوقيــع قاضــي اســتئناف ‪........‬‬\n‫ختــم وتوقيــع رئيــس الدائــرة ‪ ........‬ختــم وتوقيــع عليــه فقــد أمــرت بإثباتــه‬\n‫علــى ضبطــه وســجله حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/14‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى الصــك الصــادر مــن فضيلــة الشــيخ (‪ )........‬القاضــي باحملكمــة‬\n‫العامــة بجــدة املــؤرخ يف ‪1433/11/16‬ه ـ واملســجل بعــدد ‪33455749‬‬\n‫املتضمــن دعــوى (‪ )........‬ضــد (‪ )........‬يف فســخ نــكاح ‪ ،‬وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                             ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":356,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"771689708f6f843c8890e6393529f79a6e4159896b937b243788311ac3cca9aa","normalized_text_hash":"643d2041a8721678cc4c58a2c52765e23b139a520643704a70b91544962ac9fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p356-33455749"},{"id":"31efc675-be13-5741-bca9-6d6c3c6a7aaa","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -عدم الدخول أو اخللوة بن الزوجن -مطالبة الزوجة بالفسخ للغياب وعدم النفقة -شهادة الشهود واليمن -إقرار والد الزوج باختال ابنه العقلي وعدم كفاءته كزوج -عدم النفقة أحد موجبات الفسخ -احلكم غيابيا بفسخ النكاح دون عوض .","document_number":"34305506","case_number":"33503229","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/24","year":"1434","subject":"فسخ نكاح -عدم الدخول أو اخللوة بن الزوجن -مطالبة الزوجة بالفسخ للغياب وعدم النفقة -شهادة الشهود واليمن -إقرار والد الزوج باختال ابنه العقلي وعدم كفاءته كزوج -عدم النفقة أحد موجبات الفسخ -احلكم غيابيا بفسخ النكاح دون عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/24 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34305506 :‬‬\n                         ‫َر ْق ُم الدعوى‪33503229 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34337626‬تاريخه‪1434/10/22:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬عــدم الدخــول أو اخللــوة بــن الزوجــن ‪ -‬مطالبــة الزوجــة‬\n      ‫بالفســخ للغيــاب وعــدم النفقــة ‪ -‬شــهادة الشــهود واليمــن‪ -‬إقــرار والــد‬\n      ‫الــزوج باختــال ابنــه العقلــي وعــدم كفاءتــه كــزوج ‪ -‬عــدم النفقــة‬\n          ‫أحــد موجبــات الفســخ ‪ -‬احلكــم غيابيــا بفســخ النــكاح دون عــوض ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــال ابــن فرحــون يف تبصــرة احلــكام‪ « :‬البــاب األربعــون يف القضــاء‬\n      ‫بالشــهادة بغلبــة الظــن‪« :‬واعلــم أن الشــرع لــم يعتبــر مطلــق الظــن‬\n      ‫يف غالــب املســائل ‪ ،‬وإمنــا يعتبــر ظنونــا مفيــدة مســتفادة مــن أمــارة‬\n      ‫مخصوصــة ‪ ،‬وذلــك فيمــا ال ســبيل فيــه إلــى القطــع « إلــى أن قــال‬\n      ‫«مســألة ‪ /‬وكذلــك الشــهادة المــرأة غــاب زوجهــا وتركهــا بغيــر‬\n      ‫نفقــة‪ ،‬ألن الشــهادة فيــه علــى الغلبــة دون البــت فــإن قامــت بذلــك عنــد‬\n      ‫احلاكــم وشــهد لهــا الشــهود اســتظهر عليهــا باليمــن علــى صحــة مــا‬\n      ‫شــهد بــه الشــهود لهــا ‪ ،‬فبمقارنــة اليمــن للشــهادة وجــب لهــا احلكــم‬\n                                                                 ‫بذلــك» (‪.)14/2‬‬\n      ‫‪ .2‬قــال يف اإلقنــاع « وإن كان الــزوج غائبــا ولــم يتــرك لهــا نفقــة ولــم‬\n      ‫يقــدر علــى مــالٍ لــه وال األخــذ مــن وكيلــه إن كان لــه وكيــل كتــب‬\n      ‫احلاكــم إليــه فــإن لــم يعلــم خبــره وتعــذرت النفقــة كمــا تقــدم فلهــا‬\n                                                                       ‫الفســخ « أ‪.‬ه ـ‬\n\n‫‪363‬‬\n\f‫‪ .3‬قــال يف كشــاف القنــاع يف معــرض االستشــهاد علــى أن اإلعســار‬\n‫بالنفقــة الواجبــة أحــد موجبــات الفســخ ‪ « :‬وهــو قــول عمــر وعلــي‬\n‫وأبــو هريــرة لقولــه تعالــى (فإمســاك مبعــروف أو تســريح بإحســان)‬\n‫البقــرة‪ »229‬وليــس اإلمســاك مــع تــرك اإلنفــاق إمســاكا مبعــروف‬\n‫فتعني التسريح‪ .‬وقال صلى اهلل عليه وسلم « امرأتك تقول أطعمني‬\n‫وإال فارقنــي» رواه أحمــد والــدار قطنــي والبيهقــي بإســناد صحيــح ورواه‬\n‫الشــيخان مــن قــول أبــي هريــرة ‪ ،‬وروى الشــافعي وســعيد عــن ســفيان‬\n‫عــن أبــي الزنــاد قــال « ســألت ســعيد بــن املســيب عــن الرجــل ال يجــد‬\n‫مــا ينفــق علــى امرأتــه ؟ قــال ‪ :‬يفــرق بينهمــا قــال أبــو الزنــاد لســعيد ‪:‬‬\n‫ســنة؟ قــال ســعيد ســنة « وألن هــذا أولــى بالفســخ مــن العجــز بالــوطء‬\n‫وكان علــى التراخــي ألنــه كخيــار العيــب ) أ‪.‬ه ـ ‪ .‬قــال احلافــظ ابــن‬\n‫حجــر يف البلــوغ يف أثــر ســعيد ‪»:‬إســناده قــوي « ‪ ،‬ومراســيل ابــن املســيب‬\n                                                    ‫أقــوى مراســيل التابعــن ‪.‬‬\n\n\n\n\n‫حضــر املدعــي وكالـ ًة‪ ،‬وادعــى علــى املدعــى عليــه الغائــب عــن مجلــس‬\n‫احلكــم أنــه تــزوج موكلتــه علــى مهــر قــدره عشــرون ألــف ريــال‪ ،‬ســلم‬\n‫منه خمســة آالف ريال والباقي مؤجل يســلمه يف ‪1433/3/20‬هـ إال أنه‬\n‫ـيس وال خلوة‪،‬وبعــد العقــد‬‫لــم يســلم منــه شــيئا ‪ ،‬ولــم يحصــل بينهمــا مسـ ٌ‬\n‫بشــهر تقريبا غاب وأصبح ال يســأل عنها وال يعلمون مكانه‪،‬وانقطعت‬\n‫جميــع ســبل التواصــل معــه حتــى عــن طريــق أهلــه‪ ،‬كمــا ظهــر ملوكلتــه‬\n‫أنــه غيــر ســوي يف كالمــه ويهــذي بأقــوال وتصرفات ال تصدر من عاقل‬\n‫وأن موكلتــه تضــررت مــن بقائهــا معلقــة بــا نفقــة وال زوج يصونهــا لــذا‬\n\n                                                                                      ‫‪364‬‬\n\f      ‫فإنهــا تطلــب فســخ نكاحهــا منــه ‪ -‬مت طلــب البينــة مــن املدعــي وكالــة‬\n      ‫علــى دعــواه فأحضــر شــاهدين‪ ،‬ومت ســماع شــهادتهما‪ ،‬وتعديلهمــا ‪،‬‬\n      ‫حضــر والــد املدعــى عليــه‪ ،‬وبعــرض دعــوى املدعيــة عليــه قــرر أن ابنــه‬\n      ‫مختــل عقليــا وأنــه كان رافضــا تزويجــه يف أول األمــر‪ ،‬كمــا قــرر أن‬\n      ‫ابنــه املدعــى عليــه لــم يســلم مــن املهــر إال خمســة آالف ريــال أخذهــا مــن‬\n      ‫والدتــه ‪ ،‬وأنــه يشــفع للمدعيــة أن ُيخلــى ســبيلها ألن املدعــى عليــه غيــر‬\n      ‫كفــؤ ليكــون زوجــا‪ ،‬وأنــه إن كان لــه عليهــا حقــا ماليــا فإنــه يبرئهــا‬\n      ‫منــه هكــذا قــرر ‪ ،‬ورد خطــاب مديــر مكتــب مأذوني األنكحة املرفق‬\n      ‫بــه صــورة ضبــط عقــد نــكاح املدعيــة مــن املدعــى عليــه املشــار فيــه‬\n      ‫إلــى أن املهــر عشــرون ألــف ريــال ســلم خمســة آالف ريــال والباقــي يســلم‬\n      ‫يف ‪1433/3/20‬ه ـ أ‪.‬ه ـ ‪ ،‬بطلــب ميــن االســتظهار مــن املدعيــة حلفتهــا‬\n      ‫‪ -‬بنــاء علــى دعــوى املدعيــة املســتوفية شــروط ســماعها حتريــرا وطلبــا‬\n      ‫واختصاصــا‪ ،‬وشــهادة الشــاهدين املعدلــن شــرعا ‪ ،‬حلــف املدعيــة ميــن‬\n      ‫االســتظهار علــى دعواهــا وإفــادة والــد املدعــى عليــه ‪ ،‬وملــا كانــت عــدم‬\n      ‫النفقــة أحــد موجبــات الفســخ ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة‬\n      ‫مــن املدعــى عليــه علــى غيــر عــوض ‪ ،‬وجــرى إفهــام املدعيــة أنهــا بانــت‬\n      ‫مــن املدعــى عليــه بينونــة صغــرى ال حتــل لــه إال بعقــد جديــد مســتوف‬\n      ‫أركانــه وشــروطه‪ ،‬وأنــه ال عــدة لهــا وأال تتــزوج حتــى يصــدق احلكــم‬\n      ‫مــن محكمــة االســتئناف ‪ ،‬لصــدور احلكــم علــى غائــب مت رفعــه‬\n      ‫حملكمــة االســتئناف ‪ ،‬ورد احلكــم مصدقــا مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫(‪ )........‬القاضــي باحملكمــة العامــة مبكــة املكرمة وبنــاء على املعاملة‬\n‫املقيــدة بأســاس احملكمــة برقــم ‪ 331190980‬يف ‪1433/6/24‬ه ـ‬\n‫احملالــة لنــا بشــرح فضيلــة رئيــس احملكمــة برقــم ‪ 33503229‬فتحــت‬\n‫اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر (‪ )........‬ســعودي اجلنســية‬\n‫مبوجــب بطاقــة األحــوال الصــادرة مــن إدارة األحــوال مكــة بالســجل‬\n‫املدنــي رقــم (‪ )........‬وكيــا عــن أختــه (‪ )........‬مبوجــب صــك الوكالــة‬\n‫الصــادر مــن كتابــة عــدل الثانيــة بغــرب مكــة برقــم ‪ 33134622‬يف‬\n‫‪1433/6/24‬ه ـ املخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوى وســماع‬\n‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح واإلبــراء ‪...‬الــخ‬\n‫وطلــب النظــر يف دعــوى موكلتــه ضــد (‪ )........‬بالســجل املدنــي رقــم‬\n‫…‪ ..‬حيــث جــرى حتديــد موعــد للنظــر يف الدعــوى يف يــوم األربعــاء‬\n‫‪1433/10/11‬ه ـ الســاعة (‪ )10:00‬ص وقــد وردتنــا اإلفــادة مــن محضر‬\n‫اخلصــوم باحملكمــة ‪ ........‬بأنــه جــرى االتصــال علــى هاتفه رقــم (‪)..........‬‬\n‫واســتعد باحلضــور للجلســة وأنــه طلــب االكتفــاء بذلــك إال أنــه لم يحضر‬\n‫‪ ،‬فجــرى الكتابــة لشــرطة احملاكــم بطلــب إحضــاره بالقــوة اجلبريــة‬\n‫فوردنتــا اإلفــادة مــن شــرطة الشــرائع بأنــه جــرى البحــث والتحــري عنــه‬\n‫علــى ضــوء عنوانــه بالكتــاب واتضــح بأنــه ال يســكن اجلعرانــة وأنــه‬\n‫جــرى تبليــغ والــده وأقــر بــأن ابنــه ال يســكن اجلعرانــة وال يعلــم عنــه شــيئا‬\n‫وأنــه كان يعمــل بشــرطة احلــرم وفصــل مــن عملــه ومنقطــع عنــه منــذ‬\n‫فتــرة أ‪.‬ه ـ وبعرضــه علــى وكيــل املدعيــة قــرر بأنــه ال يعلــم لــه عنوانــا‬\n\n                                                                                         ‫‪366‬‬\n\f      ‫ســواه عليــه فجــرت الكتابــة ألمــارة املنطقــة بطلــب إعالمــه مبوعــد‬\n      ‫اجللســة املقــررة يف يــوم الثالثــاء ‪1434/5/21‬ه ـ فوردنــا كتــاب شــرطة‬\n      ‫محافظــة الكامــل برقــم ‪ 6/2/20/1204‬يف ‪1434/4/16‬ه ـ املشــار‬\n      ‫فيــه لكتــاب أمــارة املنطقــة بطلــب تعميــد إبالغــه مبوعــد اجللســة وقــد‬\n      ‫تضمــن خطــاب شــرطة الكامــل بأنــه بالبحــث والتحري عنــه باحملافظة‬\n      ‫لــم يتــم العثــور عليــه أ‪.‬ه ـ كمــا وردنــا خطــاب مديــر شــعبة التحريــات‬\n      ‫والبحــث اجلنائــي رقــم ‪ 509971‬يف ‪1434/6/14‬ه ـ بأنــه جــرى إدراج‬\n      ‫اســم املدعــى عليــه يف قائمــة إيقــاف اخلدمــات ‪ .‬ووردنــا أيضــا خطــاب‬\n      ‫مديــر شــرطة محافظــة الطائــف رقــم ‪ 2137‬يف ‪1434/7/15‬ه ـ املبنــي‬\n      ‫علــى خطــاب مديــر مخفــر بنــي ‪ ...‬رقــم ‪ ...‬يف ‪1434/6/19‬ه ـ بأنــه‬\n      ‫جــرى االتصــال علــى رقــم جــوال والــده وأنــه ذكــر بــأن ولــده يســكن‬\n      ‫معــه وأنــه أفادهــم بــأن قضيــة ابنــه انتهــت باخللــع أ‪.‬ه ـ مضمونــه مــع العلــم‬\n      ‫بأنــه لــم يصــدر منــا شــيء بخصوصــه حينهــا ‪ ،‬ولــم تردنــا إفــادة مــن أي‬\n      ‫جهــة أخــرى حتــى اآلن ‪ ،‬عليــه فقــد أذنــت لــه بســماع دعواهــا ضــده‬\n      ‫فادعــى قائــا إن املدعــى عليــه ‪ ........‬زوج موكلتــي عقــد عليهــا بواليتــي‬\n      ‫علــى مهــر عشــرين ألــف ريــال وقــد جــرى توثيقــه بالعقــد الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪............‬يف ‪1433/1/20‬ه ـ ســلم منــه خمســة آالف‬\n      ‫ريــال والباقــي يســلمه يف ‪1433/3/20‬ه ـ إال أنــه لــم يســلم منــه شــيئا‬\n      ‫حتــى اآلن كمــا لــم يحصــل بينهمــا مســيس وال خلــوة وبعــد العقــد بشــهر‬\n      ‫تقريبــا غــاب عنــا وأصبــح ال يســأل عنهــا وال نعلــم مكانــه وانقطعــت‬\n      ‫جميــع ســبل التواصــل معــه حتــى عــن طريــق أهلــه وقــد ظهــر ملوكلتــي‬\n      ‫مــن كالمــه أنــه غيــر ســوي يف كالمــه ويهــذي بأقــوال وتصرفــات‬\n      ‫ال تصــدر مــن عاقــل وقــد تضــررت موكلتــي مــن بقائهــا معلقــة بــا‬\n\n\n‫‪367‬‬\n\f‫نفقــة وال زوج يصونهــا لــذا فــإن موكلتــي تطلــب فســخ نكاحهــا منــه‬\n‫هــذه دعــواي ‪ ،‬فجــرى االطــاع علــى صــورة ضوئيــة مــن وثيقــة العقــد‬\n‫فوجدتهــا تتضمــن توثيــق عقــد زواج املدعــى عليــه مــن املدعيــة بواليــة‬\n‫والدهــا علــى مهــر عشــرين ألــف ريــال ســلم مــن خمســة آالف ريــال‬\n‫والباقــي يســلمه يف ‪1433/3/20‬ه ـ فطلبــت منــه البينــة علــى دعــواه‬\n‫فأحضــر ‪ .......‬ســعودي اجلنســية املولــود يف ‪1408/10/15‬ه ـ مبوجــب‬\n‫بطاقــة األحــوال الصــادرة مــن أحــوال مكــة بالســجل رقــم ‪ ......‬وقــرر‬\n‫بأنــه متســبب وابــن خالــة املدعيــة وال تربطــه صلــة قرابــة باملدعــى عليــه‬\n‫كمــا أحضــر ‪ ......‬ســعودي اجلنســية املولــود يف ‪1406/4/21‬ه ـ مبوجــب‬\n‫بطاقــة األحــوال الصــادرة مــن إدارة األحــوال مبكــة بالســجل رقــم ‪........‬‬\n‫وقــرر بأنــه متســبب وجــار للوالــد املدعيــة حيــث تســكن مــع والدهــا وال‬\n‫تربطــه صلــة قرابــة باملدعــى عليــه وقــد شــهد كل واحــد منهمــا منفــردا‬\n‫قائــا أشــهد بــاهلل تعالــى بــأن املدعــى عليــه ‪ .........‬زوج املدعيــة ‪.........‬‬\n‫تزوجهــا يف ‪1433/1/20‬ه ـ وأنــه بعــد العقــد بشــهر انقطــع عنهــا وأصبــح‬\n‫ال يتواصــل معهــا وقــد قــام أهلهــا بالســؤال والتحــري عنــه وكنــا ممــن‬\n‫حتــرى وســأل عنــه فلــم جنــد لــه أثــرا وقــد ظهــر لنــا بأنــه هجرها ال يســأل‬\n‫عنهــا وال يبعــث لهــا بنفقــة هــذا مــا لــدي وبــه أشــهد وبســؤاله البينــة علــى‬\n‫عدالــة الشــاهدين أحضــر ‪ ..............‬ســعودي اجلنســية مبوجــب بطاقــة‬\n‫األحــوال بالســجل املدنــي رقــم ‪ .........‬و‪ ...........‬مبوجــب بطاقــة األح ــوال‬\n‫بالســجل املـ ــدني رقـ ــم ‪ .........‬وشــهد كل واحــد منهمــا منفــردا بعدالــة‬\n‫الشــاهدين ظاهــرا وباطنــا وأنهمــا ال يعلمــان عليهمــا مطعــن ال يف دينهمــا‬\n‫وال أمانتهمــا ويقبــان شــهادتهما لهمــا وعليهمــا ‪ ،‬وقــد جــرى االتصــال‬\n‫علــى والــده وطلــب حضــوره فحضــر ويحمــل بطاقــة األحــوال الصــادرة‬\n\n\n                                                                                         ‫‪368‬‬\n\f      ‫مــن إدارة أحــوال مكــة بالســجل رقــم ‪ ..........‬وبعــرض الدعــوى عليــه‬\n      ‫وســؤاله عمــا لديــه أجــاب قائــا إن ابنــي ‪ ..........‬لديــه مختــل عقليــا وقــد‬\n      ‫رافضــا تزويجــه يف أول األمــر وبعــد ضغــط مــن والدته وأخواتــه وإخواني‬\n      ‫وإخوتــه لعــل اهلل يشــفيه ويصلــح حالــه خصوصــا وأنــه توظــف يف أبــراج‬\n      ‫الوقــف فاســتجبت لضغوطهــم وضميــري يؤنبنــي خوفــا مــن أضــر بنــت‬\n      ‫النــاس معــه وممــا زادنــي حســرة بأنــي لــم أخبــر وليهــا بحالــه ومــا كنــت‬\n      ‫أخشــاه حصــل ‪ ،‬فلمــا علمــت مبوعــد اجللســة يف مكتــب الصلــح العــام‬\n      ‫املاضــي ســحبته معــي طالبــا منــه أن يســرح املدعيــة ويتركهــا حلالهــا‬\n      ‫إال أنــه رفــض الدخــول يف املكتــب وانفلــت مــن يــدي وخــرج مــن املنــزل‬\n      ‫وتــرك وظيفتــه ولــم يعــد حتــى اآلن وال أعلــم مكانــه ولــم أســمع عنــه‬\n      ‫خبــرا مــن ذلــك اليــوم حتــى اليــوم وطلبــت مــن إخوتــه أال يعطــوه مــاال إن‬\n      ‫اتصــل بهــم لعلــه يعــود لــي وهــو لــم يســلم مــن املهــر إال خمســة آالف ريــال‬\n      ‫أخذهــا منــه والدتــه ‪ ،‬وأنــي أشــفع لهــا عندكــم بــأن تخلــوا ســبيلها منــه‬\n      ‫فهــو غيــر كفــؤ ليكــون زوجــا وإن كان لــه عليهــا حقــا ماليــا فإنــي‬\n      ‫أبرئها منها أ‪.‬هـ ويف يوم االثنني ‪1434/8/15‬هـ فتحت اجللســة الســاعة‬\n      ‫الثامنــة صباحــا وفيهــا حضــرت املدعيــة ‪............‬بالســجل رقــم ‪ ..........‬مــع‬\n      ‫وكيلهــا ‪ ،‬وقــد وردنــا خطــاب مديــر مكتــب مأذونــي األنكحــة رقــم‬\n      ‫‪ 341570714‬يف ‪1434/8/14‬ه ـ واملرفــق بــه صــورة ضبــط عقــد نــكاح‬\n      ‫املدعيــة مــن املدعــى عليــه املــدون علــى الصحيفــة رقــم ‪ 42‬واملــؤرخ يف‬\n      ‫‪1433/1/20‬ه ـ املجلــد الثامــن بواســطة املــأذون ‪ ...............‬وقــد أشــير‬\n      ‫فيــه بــأن املهــر عشــرون ألــف ريــال ســلم خمســة آالف ريــال والباقــي‬\n      ‫يســلم يف ‪1433/3/20‬ه ـ أ‪.‬ه ـ مضمونــه ‪ ،‬فطلبــت منهــا ميــن االســتظهار‬\n      ‫علــى دعواهــا فحلفــت قائلــة « واهلل العظيــم بــأن املدعــى عليــه زوجــي‬\n\n\n‫‪369‬‬\n\f‫‪ .............‬تركنــي بعــد زواجــي معلقــة بــا نفقــة ولــم يســلم لــي باقــي املهــر‬\n‫حتــى اآلن وقــد تعــذر علــي االســتدانة عليــه لإلنفــاق علــى نفســي « ‪،‬‬\n‫عليــه وبعــد قفــل بــاب املرافعــة ‪ ،‬وبنــاء علــى دعــوى املدعيــة املســتوفاة‬\n‫شــروط ســماعها حتريــرا وطلبــا واختصاصــا ‪ ،‬وبنــاء علــى إفــادة شــرطة‬\n‫الشــرائع ‪ ،‬وعلــى التعميــم عليــه مــن قبــل اإلمــارة علــى إفــادة شــرطة‬\n‫الكامــل ‪ ،‬عليــه وبنــاء علــى شــهادة الشــاهدين املعدلــن شــرعا بــأن‬\n‫املدعــى عليــه هجــر زوجتــه وتركهــا معلقــة بــا نفقــة ‪ ،‬عليــه ولصحــة‬\n‫الشــهادة بغلبــة الظــن واحلــال هــذه للحاجــة ‪ ،‬قــال ابــن فرحــون يف تبصــرة‬\n‫احلــكام ‪ « :‬البــاب األربعــون يف القضــاء بالشــهادة بغلبــة الظــن ‪ :‬وأعلــم‬\n‫أن الشــرع لــم يعتبــر مطلــق الظــن يف غالــب املســائل ‪ ،‬وإمنــا يعتبــر ظنونــا‬\n‫مفيــدة مســتفادة مــن أمــارة مخصوصــة ‪ ،‬وذلــك فيمــا ال ســبيل فيــه إلــى‬\n‫القطــع « إلــى أن قــال «مســألة ‪ /‬وكذلــك الشــهادة إلمــرأة غــاب زوجهــا‬\n‫وتركهــا بغيــر نفقــة ‪ ،‬ألن الشــهادة فيــه علــى الغلبــة دون البــت فــإن‬\n‫قامــت بذلــك عنــد احلاكــم وشــهد لهــا الشــهود اســتظهر عليهــا باليمــن‬\n‫علــى صحــة مــا شــهد بــه الشــهود لهــا ‪ ،‬فبمقارنــة اليمــن للشــهادة وجــب‬\n‫لهــا احلكــم بذلــك « (‪ ، )14/2‬عليــه وألن األصــل عــدم االنفــاق وألن‬\n‫املدعيــة حلفــت ميــن االســتظهار علــى دعواهــا وتأكيــدا لهــذا األصــل‬\n‫‪ ،‬يؤيــده مــا جــاء يف إفــادة والــد املدعــى عليــه ‪ ،‬عليــه وألن عــدم النفقــة‬\n‫أحــد موجبــات الفســخ ‪ ،‬قــال يف الكشــاف يف معــرض االستشــهاد علــى‬\n‫أن االعســار بالنفقــة الواجبــة أحــد موجبــات الفســخ ‪ « :‬وهــو قــول عمــر‬\n‫وعلــي وأبــو هريــرة لقولــه تعالــى )فإمســاك مبعــروف أو تســريح بإحســان‬\n‫) «البقــرة‪ »229‬وليــس اإلمســاك مــع تــرك اإلنفــاق إمســاكا مبعــروف‬\n‫فتعــن التســريح‪ .‬وقــال صلــى اهلل عليــه وســلم « امرأتــك تقــول أطعمنــي‬\n\n\n                                                                                           ‫‪370‬‬\n\f      ‫وإال فارقنــي» رواه أحمــد والــدار قطنــي والبيهقــي بإســناد صحيــح ورواه‬\n      ‫الشــيخان مــن قــول أبــي هريــرة ‪ ،‬وروى الشــافعي وســعيد عــن ســفيان‬\n      ‫عــن أبــي الزنــاد قــال « ســألت ســعيد بــن املســيب عــن الرجــل ال يجــد‬\n      ‫مــا ينفــق علــى امرأتــه ؟ قــال ‪ :‬يفــرق بينهمــا قــال أبــو الزنــاد لســعيد ‪:‬‬\n      ‫ســنة؟ قــال ســعيد ســنة « وألن هــذا أولــى بالفســخ مــن العجــز بالــوطء‬\n      ‫وكان علــى التراخــي ألنــه كخيــار العيــب ) أ‪.‬ه ـ ‪ .‬قــال احلافــظ ابــن‬\n      ‫حجــر يف البلــوغ يف أثــر ســعيد ‪»:‬إســناده قــوي « ‪ ،‬ومراســيل ابــن املســيب‬\n      ‫أقــوى مراســيل التابعــن ‪ ،‬عليــه وألن حكــم الــزوج الغائــب الــذي لــم‬\n      ‫يتــرك نفقــة حكــم املعســر بهــا أو ببعضهــا قــال يف اإلقنــاع « وإن كان‬\n      ‫الــزوج غائبــا ولــم يتــرك لهــا نفقــة ولــم يقــدر علــى مــال لــه وال األخــذ مــن‬\n      ‫وكيلــه إن كان لــه وكيــل كتــب احلاكــم إليــه فــإن لــم يعلــم خبــره‬\n      ‫وتعــذرت النفقــة كمــا تقــدم فلهــا الفســخ « أ‪.‬ه ـ عليــه وملجمــوع مــا تقــدم‬\n      ‫فقــد فســخت هــذا اليــوم االثنــن ‪1434/8/15‬ه ـ نــكاح ‪.......................‬‬\n      ‫مــن ‪ ....................‬علــى غيــر عــوض وأفهمتهــا بانــت منــه بينونــة صغــرى‬\n      ‫ال حتــل لــه إال بعقــد جديــد مســتوف أركانــه وشــروطه وأنــه ال عــدة‬\n      ‫لهــا وأال تتــزوج حتــى يوافــق علــى احلكــم مــن محكمــة االســتئناف‬\n      ‫ومبــا تقــدم حكمــت وجــرى النطــق بــه يف يــوم االثنــن ‪1434/8/15‬ه ـ‬\n      ‫ولصــدوره علــى غائــب فقــد قــررت رفعــه حملكمــة االســتئناف لتدقيقــه‬\n      ‫وأقفلــت اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n                                               ‫محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n      ‫يــوم األربعــاء ‪1434/8/18‬ه ـ فتحــت اجللســة الســاعة التاســعة صباحــا‬\n      ‫لإلشــارة خلطابــن األول ‪ /‬اخلطــاب الــوارد مــن مديــر شــعبة التحريــات‬\n\n\n‫‪371‬‬\n\f‫والبحــث اجلنائــي رقــم ‪ 509971‬يف ‪1434/6/14‬ه ـ بأنــه جــرى إدراج‬\n‫اســم املدعــى عليــه يف قائمــة إيقــاف اخلدمــات ‪ .‬واآلخــر مــن مديــر شــرطة‬\n‫محافظــة الطائــف رقــم ‪ 2137‬يف ‪1434/7/15‬ه ـ املبنــي علــى خطــاب‬\n‫مديــر مخفــر بنــي مالــك رقــم ‪/572‬ع يف ‪1434/6/19‬ه ـ بأنــه جــرى‬\n‫االتصــال علــى رقــم جــوال والــده وأنــه ذكــر بــأن ولــده يســكن معــه‬\n‫وأنــه أفادهــم بــأن قضيــة ابنــه انتهــت باخللــع أ‪.‬ه ـ مضمونــه ‪ ،‬مــع العلــم‬\n‫بأنــه لــم يصــدر منــا حكــم بذلــك حينهــا ‪ ،‬هــذا مــا لــزم التنويــه عنــه‬\n‫وأقفلــت اجللســة الســاعة التاســعة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬احلمــد هلل وحــده ففــي يــوم االثنــن‬\n‫‪ 1434/11/10‬ه ـ افتتحــت اجللســة الســاعة العاشــرة بعدمــا عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف بالقــرار رقــم ‪ 34337626‬وتاريــخ‬\n‫‪1434/10/22‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم مع التنبيه املرفق ‪ .‬قاضي اســتئناف ‪.........‬‬\n‫موقــع يف األصــل وموافــق علــى احلكــم ومجــاز‪ .‬قاضــي اســتئناف ‪........‬‬\n‫ختمــه وتوقيعــه ‪ .‬رئيــس الدائــرة ‪ .........‬ختمــه وتوقيعــه ) أ‪.‬ه ـ وأقفلــت‬\n‫اجللســة الســاعة العاشــرة والربــع ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/10‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلة رئيــس احملكمة العامة‬\n‫مبكــة املكرمــة رقــم ‪ 33/1190980‬وتاريــخ ‪1434/10/8‬ه ـ املشــتملة‬\n‫علــى الصــك رقــم ‪ 34305506‬وتاريــخ ‪1434/8/24‬ه ـ الصــادر مــن‬\n\n\n                                                                                     ‫‪372‬‬\n\f      ‫فضيلــة الشــيخ ‪ ........‬املتضمــن دعــوى ‪ .........‬ضــد ‪ .........‬يف فســخ نــكاح‬\n      ‫وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مــع‬\n      ‫التنبيــه املرفــق واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪373‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":363,"source_page_end":373,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aff8e75fcd2160a36c9e448ac705a333149162815b46b7496163cd16146160d3","normalized_text_hash":"b0984bc8d42881f3d8a06f81a5a31f0b34e02b456e324c162190e81731b99357","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p363-34305506"},{"id":"be09bde6-e1b4-5f88-9046-236ced7eb94e","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة وعدم املعاشرة والكراهية -رفض الزوجن الصلح -جلنة اإلصاح ترى التفريق بن الزوجن -حلف الزوجة اليمن بعدم استالمها ا -فسخ النكاح مقابل تنازل الزوجة عن املهر الذي لم","document_number":"34308961","case_number":"33600507","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/29","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة وعدم املعاشرة والكراهية -رفض الزوجن الصلح -جلنة اإلصاح ترى التفريق بن الزوجن -حلف الزوجة اليمن بعدم استالمها ا -فسخ النكاح مقابل تنازل الزوجة عن املهر الذي لم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34308961 :‬‬\n                   ‫َر ْق ُم الدعوى‪33600507 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34379480‬تاريخه‪1434/12/16:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول لعــدم النفقــة‬\n‫وعــدم املعاشــرة والكراهيــة ‪ -‬رفــض الزوجــن الصلــح ‪ -‬جلنــة اإلصــاح‬\n‫تــرى التفريــق بــن الزوجــن ‪ -‬حلــف الزوجــة اليمــن بعــدم اســتالمها‬\n‫ا ‪ -‬فســخ النــكاح مقابــل تنــازل الزوجــة عــن املهــر الــذي لــم‬\n                                                                   ‫املهــر كامـ ً‬\n                                                                       ‫تســتلمه ‪.‬‬\n\n\n\n\n‫‪ .1‬قــال يف الــروض املربــع ( وإن اختلفــا يف قبضــه فالقــول قولهــا أو‬\n‫قــول وليهــا أو وارثهــا مــع اليميـ ــن حيــث ال بينــة لــه ألن األصــل ع ـ ــدم‬\n                                                                     ‫القبــض ) ‪.‬‬\n      ‫‪ .2‬قال يف كشاف القناع‪( :‬ويصح اخللع باملجهول ) ( ‪. ) 154/12‬‬\n\n\n\n\n‫ادعــت املدعيــة أن املدعــى عليــه تزوجهــا ودخــل بهــا‪ ،‬وأجنبــت منــه علــى‬\n‫فــراش الزوجيــة ســتة أوالد‪ ،‬وأنــه هجرهــا وتركهــا هــي وأوالدهــا منــذ‬\n‫أربعــة عشــر عامــا دون نفقــة وال معاشــرة‪ ،‬وأنهــا كرهــت املدعــى عليــه‬\n‫ممــا جعلهــا تتضــرر ضــررا بالغــا يف مواصلة احلياة معــه ‪ ،‬وطلبت احلكم‬\n‫بفســخ نكاحهــا منــه‪ ،‬واســتعدت بالتنــازل عــن النفقــة املاضيــة وعــن‬\n‫مؤخــر الصــداق ‪ ،‬بعــرض دعــوى املدعيــة علــى املدعــى عليــه صادق على‬\n\n                                                                                      ‫‪374‬‬\n\f      ‫الزواج واألوالد‪ ،‬وأنكر ما سوى ذلك ‪ ،‬وقرر أنه ال يرغب يف تطليقها‬\n      ‫‪ ،‬جــرى عــرض الصلــح علــى املتداعيــن مــرارا ولــم يتوصــا لشــيء ‪ ،‬متت‬\n      ‫الكتابــة للجنــة اإلصــاح يف احملكمــة لالجتمــاع بالطرفــن ومحاولــة‬\n      ‫اإلصــاح والتوفيــق بينهمــا‪ ،‬وإن تعــذر ذلــك فيتــم بعــث حكمــن مــن‬\n      ‫قبلهــم أو مــن قبــل احملكمــة إن تعــذر ذلــك ‪ ،‬ورد اجلــواب املتضمــن رأي‬\n      ‫اللجنــة أن يخالــع الــزوج زوجتــه مقابــل املهــر املســمى يف عقــد النــكاح‬\n      ‫إن اســتلمت الزوجــة املهــر ‪ ،‬بســؤال املدعيــة عــن مقــدار املهــر قــررت أن‬\n      ‫املهــر عشــرون ألــف ليــرة ســورية‪ ،‬عشــرة آالف منهــا مقــدم ‪ ،‬وعشــرة‬\n      ‫آالف مؤخــر‪ ،‬وأنهــا لــم تســتلم منــه شــيئا‪ ،‬وأنهــا ال مانــع لديهــا مــن فســخ‬\n      ‫النــكاح مقابــل تنازلهــا عــن هــذا املهــر ‪ ،‬بعــرض ذلــك علــى املدعــى عليه‬\n      ‫قــرر أن ال يعلــم مــا ذكرتــه املدعيــة مــن مقــدار املهــر وأنــه غيــر مســلم‬\n      ‫‪ ،‬بذلــت املدعيــة اليمــن علــى عــدم اســتالمها للمهــر ‪ ،‬جلنــة اإلصــاح‬\n      ‫يف احملكمــة رأت التفريــق بــن الطرفــن علــى أن تعيــد املدعيــة املهــر‬\n      ‫كامــا وقــد ادعــت املدعيــة عــدم اســتالمها للمهــر مــن املدعــى عليــه‬\n      ‫مقدمــه ومؤخــره واألصــل عــدم اســتالم املهــر وقــد أدت املدعيــة اليمــن‬\n      ‫التــي عضــدت بــه األصــل علــى عــدم اســتالمها ‪ ،‬يصــح اخللــع باملجهــول‬\n      ‫‪ ،‬مت احلكــم بفســخ نــكاح املدعيــة مقابــل تنازلهــا عــن املهــر كامــا‬\n      ‫‪ ،‬بعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى‬\n      ‫عليــه عدمهــا ‪ -‬أفهمــت املدعيــة أن عليهــا العــدة الشــرعية مــن تاريــخ‬\n      ‫احلكــم‪ ،‬وأنهــا بانــت مــن زوجهــا بينونــة صغــرى ال حتــل لــه إال مبهــر‬\n      ‫وعقــد جديديــن وبرضاهــا وأن ال تتــزوج حتــى يكتســب احلكــم الصفــة‬\n      ‫القطعيــة ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n‫‪375‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة (‪ )........‬املســاعد برقــم ‪33600507‬‬\n‫وتاريــخ ‪1433/10/14‬ه ـ املقيــدة باحملكمة برقــم ‪ 331801377‬وتاريخ‬\n‫‪1433/10/14‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/02/24‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــرت املدعيــة (‪ )........‬ســورية اجلنســية مبوجــب اإلقامــة‬\n‫رقــم (‪ )........‬وحضــر حلضورهــا املدعــى عليــه (‪ )........‬ســوري اجلنســية‬\n‫مبوجــب اإلقامــة رقــم (‪ )........‬وبســؤال املدعيــة عــن دعواهــا أجابــت‬\n‫قائلــة إن املدعــى عليــه زوجــا لــي تــزوج بــي مبوجــب عقــد شــرعي صحيــح‬\n‫ودخــل بــي الدخــول الشــرعي وأجنبــت منــه علــى فــراش الزوجيــة ‪.......‬‬\n‫وعمرهــا اثنــان وثالثــون عامــا و‪ .........‬وعمــره تســعة وعشــرون و‪.........‬‬\n‫وعمرهــا ســتة وعشــرون عامــا و‪ ...........‬وعمــره اآلن خمســة وعشــرون‬\n‫عامــا و‪ .........‬وعمــره ثالثــة وعشــرون عامــا و‪ ..........‬وعمرهــا ثالثــة عشــر‬\n‫ســنة واملدعــى عليــه قــد هجرنــي وتركنــي وأوالدي منــذ أربعــة عشــر‬\n‫عامــا بــدون نفقــة وال معاشــرة وقــد كرهــت املدعــى عليــه ممــا جعلنــي‬\n‫أتضــرر ضــررا بالغــا يف مواصلــة احليــاة معــه لــذا أطلــب مــن فضيلتكــم‬\n‫احلكــم بفســخ نكاحــي مــن املدعــى عليــه وأنــا علــى اســتعداد بالتنــازل‬\n‫عــن النفقــة املاضيــة وعــن مؤخــر الصــداق هــذه دعــواي وبســؤالها عــن‬\n‫عقــد النــكاح أجابــت قائلــة إن أصلــه يف ســوريا وصورتــه يف اجلــوازات‬\n‫وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعيــة أجــاب قائــا مــا‬\n‫ذكرتــه املدعيــة مــن شــأن زواجي بهــا وإجنابها منــي األوالد املذكورين‬\n\n                                                                                       ‫‪376‬‬\n\f      ‫فذلــك كلــه صحيــح وأمــا مــا ذكرتــه ســوى ذلــك فهــو غيــر صحيــح وأنــا‬\n      ‫ال أرغــب يف بتطليقهــا بــل أرغــب باســتمرارها زوجــة لــي هكــذا أجــاب‬\n      ‫وقــد جــرى عــرض الصلــح علــى املتداعيــن مــرارا ولكنهمــا لــم يصــا‬\n      ‫إلــى شــيء مــن ذلــك عليــه فقــد تقــرر بعــث كامــل أوراق املعاملــة إلى جلنة‬\n      ‫اإلصــاح يف هــذه احملكمــة لالجتمــاع بالطرفــن ومحاولــة اإلصــاح‬\n      ‫والتوفيــق بينهمــا وإن تعــذر ذلــك فيتــم بعــث حكمــن مــن قبلهــم أو‬\n      ‫مــن قبــل احملكمــة إن تعــذر ذلــك وحتــى ورود اجلــواب فقــد تقــرر رفــع‬\n      ‫اجللســة وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/01/20‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــر الطرفــان أصالــة وقــد وردت املعاملــة مــن قســم اإلصــاح‬\n      ‫يف هــذه احملكمــة بالرقــم ‪ 3318101377‬وتاريــخ ‪1434/03/04‬ه ـ‬\n      ‫والــذي يتضمــن ( أنــه يف يــوم األربعــاء املوافــق ‪1434/03/04‬ه ـ حضــر‬\n      ‫الطرفــان أصالــة وجــرى محاولــة اإلصــاح بينهمــا ولكــن املدعيــة‬\n      ‫أصــرت علــى طلــب املخالعــة مــن املدعــى عليــه وقالــت ايضــا اننــي لــم‬\n      ‫اســتلم املهــر منــه وبســؤاله قــال أنــا ال اذكــر ذلــك فزواجنــا منــذ خمســة‬\n      ‫وثالثــن ســنة فنــرى أن يخالــع الــزوج زوجتــه مقابــل املهــر املســمى يف‬\n      ‫عقــد النــكاح إن اســتلمت الزوجــة املهــر والــرأي لفضيلتكــم ) أ‪.‬ه ـ ‪.‬‬\n      ‫وقــرر املدعــى عليــه بقولــه إن املدعيــة لــم متكننــي مــن نفســها أكثــر‬\n      ‫مــن ثالثــة عشــر عامــا وقــد تضــررت أنــا مــن ذلــك وهــي رافضــة لالنقيــاد‬\n      ‫لبيــت الزوجيــة والطاعــة وترفــض إعطائــي حقوقــي الزوجيــة وتتجاهــل‬\n      ‫حيــث قــال الرســول صلــى اهلل عليــه وســلم ( مــا نامــت امــرأة زوجهــا‬\n      ‫غاضبــا عليهــا إال ولعنتهــا املالئكــة حتــى تصبــح ) وجميــع مــا ذكرتــه‬\n      ‫زوجتــي املذكــورة يف دعواهــا غيــر صحيــح وال أســاس لــه مــن الصحــة‬\n      ‫وبعــرض ذلــك علــى املدعيــة قالــت إنــه قــد تعــذر الصلــح بيننــا ولســت‬\n\n\n‫‪377‬‬\n\f‫راغبــة يف هــذا الــزوج وأنــا معلقــة منــذ أكثــر مــن ثالثــة عشــر عامــا ‪،‬‬\n‫هكــذا قــررت ‪ .‬وبســؤال املدعيــة عــن مقــدار املهــر قالــت إن املهــر هــو‬\n‫عشــرون ألــف ليــرة ســورية غيــر مســلمة حتــى اآلن وال مانــع لــدي مــن‬\n‫فســخ النــكاح مقابــل تنازلــي عــن هــذا املهــر وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال مــا ذكرتــه املدعيــة مــن مقــدار املهــر وأنــه غيــر مســلم فــا‬\n‫علــم لــي بــه وال أذكــر شــيئا مــن ذلــك هكــذا قــرر فطلبــت مــن املدعيــة‬\n‫إحضــار عقــد الزوجيــة لالطــاع عليــه والتأكــد مــن مقــدار املهــر وهــل‬\n‫هو مسلم أم ال فاستعدت بذلك يف اجللسة املقررة يف يوم االثنني املوافق‬\n‫‪1434/08/29‬ه ـ وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/08/29‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــرت املدعيــة ‪ ............‬وحضــر حلضورهــا املدعــى عليــه‬\n‫‪ .............‬وبســؤال املدعيــة عــن مقــدار املهــر فأجابــت قائلــة إن مقــدار‬\n‫املهــر عشــرون ألــف ليــرة ســورية عشــرة آالف منهــا مقــدم وعشــرة آالف‬\n‫مؤخــر ولــم أقــم باســتالم شــيء منهــا وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب قائــا ال أعلــم عــن مقــدار املهــر وال أعلــم عــن اســتالم املدعيــة‬\n‫لــه مــن عــدم ذلــك وذلــك لكــون هــذا قــد حــدث قدميــا قبــل مــا يقــارب‬\n‫خمســة وثالثــون ســنة ‪ .‬وبســؤال املدعيــة وهــل لديهــا اســتعداد علــى أداء‬\n‫اليمــن الالزمــة علــى عــدم اســتالمها للمهــر منــه كامــا املقــدم منــه‬\n‫واملؤخــر فأجابــت قائلــة نعــم لــدي اســتعداد بذلــك فتلفظــت املعديــة يف‬\n‫مجلــس احلكــم قائلــة واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب‬\n‫والشــهادة أننــي لــم أســتلم مــن زوجــي املدعــى عليــه ‪ .........‬مهــر زواجــي‬\n‫كامــا وال جــزء منــه واهلل العظيــم وقــد قــررت املدعيــة قائلــة إننــي‬\n‫أطلــب احلكــم بخلعــي مــن املدعــى عليــه مقابــل تنازلــي عن املهــر كامال‬\n‫مقدمــه ومؤخــره فبنــاءا علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n\n\n                                                                                     ‫‪378‬‬\n\f      ‫أن املدعيــة تطلــب فســخ النــكاح مــن املدعــى عليــه وحيــث أن املدعــى‬\n      ‫عليــه دفــع بعــدم رغبتــه يف ذلــك وحيــث أنــه قــد جــرى محاولــة الصلــح‬\n      ‫بينهمــا ولكــن لــم يصــا إلــى شــيء مــن ذلــك وحيــث أن جلنــة اإلصــاح‬\n      ‫يف هــذه احملكمــة قــد رأت التفريــق بينهمــا علــى أن تعيــد املدعيــة املهــر‬\n      ‫كامــا وحيــث أن املدعيــة ادعــت عــدم اســتالمها للمهــر مــن املدعــى‬\n      ‫عليــه مقدمــه ومؤخــره وحيــث أن املدعــى عليــه قــد دفــع بعــدم علمــه عــن‬\n      ‫ذلــك فلــم يــدع اســتالم املدعيــة للمهــر كــي يطالــب بالبينــة وحيــث أن‬\n      ‫األصــل هــو عــدم اســتالم املهــر وحيــث أن املدعيــة قامــت بــأداء اليمــن‬\n      ‫التــي عضــدت بــه األصــل علــى عــدم اســتالمها وحيــث أنــه يصلــح اخللــع‬\n      ‫باملجهــول قــال يف العــرض املربــع ( وإن اختلفــا يف قبضــه فالقــول قولهــا‬\n      ‫أو قــول وليهــا أو وارثهــا مــع اليمــن حيــث ال بينــة لــه ألن األصــل عــدم‬\n      ‫القبض ) قال يف كشاف القناع ( ويصح اخللع باملجهول ) ( ‪) 154/12‬‬\n      ‫وحيــث أن املدعيــة قــررت طلــب الفســخ مقابــل تنازلهــا عــن املهــر كامــا‬\n      ‫جلميــع مــا تقــدم فقــد فســخت نــكاح املدعيــة ‪ ........‬مــن زوجهــا ‪.............‬‬\n      ‫مقابــل تنازلهــا عــن املهــر كامــا وبذلــك حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــررت املدعيــة القناعــة باحلكــم وقــرر املدعــى عليــه عدم‬\n      ‫قناعتــه باحلكــم وأفهمــت املدعيــة بــأن عليهــا العــدة الشــرعية مــن تاريــخ‬\n      ‫هــذا اليــوم حســب حالهــا وأنهــا بانــت مــن زوجهــا بينونــة صغــرى ال حتــل‬\n      ‫لــه إال مبهــر وعقــد جديديــن وبرضاهــا وأفهمتهــا بأنهــا ال تتــزوج حتــى‬\n      ‫يكتســب احلكــم الصفــة القطعيــة ففهمــت ذلــك وجــرى تســليم املدعــى‬\n      ‫عليــه نســخة مــن صــك احلكــم لالعتــراض عليــه وجــرى إفهامــه بــأن لــه‬\n      ‫ثالثــون يومــا اعتبــارا مــن تاريــخ هــذا اليــوم لتقــدمي الئحتــه االعتراضيــة‬\n      ‫وجــرى إفهامــه بأنــه يف حالــة تأخــره عــن تقــدمي الئحتــه االعتراضيــة‬\n\n\n‫‪379‬‬\n\f‫خــال املــدة النظاميــة فــإن احلكــم يكتســب الصفــة القطعيــة ويســقط‬\n‫حقــه يف االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 331801377‬وتاريــخ‬\n‫‪1435/01/01‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 331801377‬وتاريــخ‬\n‫‪1435/01/09‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة الثانيــة لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪ 34379480‬وتاريــخ ‪1434/12/16‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم مــع مالحظــة‬\n‫التنبيــه واهلل املوفــق ) ‪ .‬أ‪.‬ه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع ‪...........‬‬\n‫األزوري وقاضــي اســتئناف ختــم وتوقيــع ‪ ..........‬ورئيــس الدائــرة ختــم‬\n‫وتوقيــع ‪ ، ......‬عليــه فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                       ‫يف ‪1435/01/11‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪ .............‬القاضــي باحملكمــة العامــة مبحافظــة جــدة برقــم ‪34308961‬‬\n‫وتاريــخ ‪1434/8/29‬ه ـ املتضمــن دعــوى‪ .......... /‬ضــد‪ ........ /‬يف فســخ‬\n\n\n                                                                                   ‫‪380‬‬\n\f      ‫نــكاح وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم مــع مالحظــة التنبيــه املرفــق واهلل املوفــق وصلــى‬\n                            ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪381‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":374,"source_page_end":381,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c0125d958b90af99673c318c287cb3521da51c818632ae2850bd8d2fa825ef74","normalized_text_hash":"62e28497db565176039f59fd81ee4ae479d431115b19dc6597433474293a36b7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p374-34308961"},{"id":"2b51638c-327e-5068-a04b-61a838e7e3f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -املطالبة بفسخ نكاح من غير دخول بسبب املرض النفسي -إقرار والد املدعى عليه مبرض ابنه (الزوج) -إثبات التقرير الطبي مرض املدعى عليه -املرض عيب موجب للفسخ - احلكم بفسخ النكاح مع إعادة املهر .","document_number":"34252367","case_number":"34122081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/26","year":"1434","subject":"فسخ نكاح -املطالبة بفسخ نكاح من غير دخول بسبب املرض النفسي -إقرار والد املدعى عليه مبرض ابنه (الزوج) -إثبات التقرير الطبي مرض املدعى عليه -املرض عيب موجب للفسخ - احلكم بفسخ النكاح مع إعادة املهر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34252367 :‬‬\n                   ‫َر ْق ُم الدعوى‪34122081 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34374316‬تاريخه‪1434/12/1 :‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬املطالبــة بفســخ نــكاح مــن غيــر دخــول بســبب املــرض‬\n‫النفســي‪ -‬إقــرار والــد املدعــى عليــه مبــرض ابنــه (الــزوج) ‪ -‬إثبــات‬\n‫التقريــر الطبــي مــرض املدعــى عليــه ‪ -‬املــرض عيــب موجــب للفســخ ‪-‬‬\n                              ‫احلكــم بفســخ النــكاح مــع إعــادة املهــر ‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬قاعدة إزالة الضرر ‪.‬‬\n‫‪ -2‬مــا ذكــره القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة يف‬\n                                                             ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫أقامــت زوجــة دعــوى تطالــب فســخ نكاحهــا مــن زوجهــا ملرضــه النفســي‬\n‫وتصرفاتــه الغيــر طبيعيــة وعــدم دخولــه بهــا ‪ ،‬لــم يحضــر املدعــى عليــه‬\n‫وحضــر والــد املدعــى عليــه وأقــر مبــا جــاء يف دعــوى املدعيــة وأن ابنــه‬\n‫املدعــى عليــه مصــاب مبــرض نفســي لــم يســتطع بســببه إحضــاره إلــى‬\n‫احملكمــة وقــرر والــد املدعــى عليــه أنــه ال مانــع لديــه مــن إجــراء الوجــه‬\n‫الشــرعي فســألت احملكمــة والــد املدعــى عليــه عن ســبب عــدم توكيله‬\n‫لــه أو اســتخراج صــك واليــة عليــه فأجــاب بــأن ابنــه مريــض نفســي‬\n‫ويرفــض اخلــروج ألي مــكان ويرفــض الذهــاب إلــى املستشــفى ‪ ،‬اطلعــت‬\n\n                                                                                      ‫‪382‬‬\n\f      ‫احملكمــة علــى التقريــر الطبــي الصــادر مــن املستشــفى الرســمي املثبــت‬\n      ‫ملــرض املدعــى عليــه مرضـ ًا نفســيا يســمى انفصام الشــخصية وألن هذا‬\n      ‫املــرض عيــب يف الــزوج يوجــب الفســخ وال يتحقــق معــه مقاصــد النــكاح‬\n      ‫يف الشــريعة وألن الشــريعة جــاءت بإزالــة الضــرر لــذا جعلــت احملكمــة‬\n      ‫للمدعيــة حــق فســخ نكاحهــا مــن املدعــى عليــه ففســخت نفســها منــه‬\n      ‫وأعــادت لــه كامــل املهــر فأثبتــت احملكمــة الفســخ وأفهمــت املدعيــة‬\n      ‫بأنهــا قــد بانــت مــن املدعــى عليــه بينونــة صغــرى ثــم ســلم والــد املدعيــة‬\n      ‫لوالــد املدعــى عليــه املهــر ونظــرا لكــون احملكــوم عليــه مريضـ ًا عقليـ ًا‬\n         ‫ولــم يحضــر رفــع هــذا اإلجــراء حملكمــة االســتئناف وصــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة (‪ )........‬وتاريــخ ‪1434/03/15‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪1434/3/15‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/06/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪02 : 00‬وفيهــا حضــرت (‪ )........‬اجلنســية‬\n      ‫(‪ )........‬مبوجــب اإلقامــة رقــم (‪ )........‬واملعــرف بهــا مــن قبــل والدهــا‬\n      ‫(‪ )........‬مينــي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬ولــم يحضــر‬\n      ‫املدعــى عليــه (‪ )........‬وحضــر والــده (‪ )........‬ســعودي اجلنســية مبوجــب‬\n      ‫(‪ )........‬ووالدتــه (‪ )........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )........‬وأفــاد والــداه قائلــن إن ابننــا يف املنــزل ولــم نســتطع إحضــاره‬\n      ‫حيــث إنــه بعــد زواجــه تغيــر وأصبــح يف حالــة نفســية صعبــة وقــد حاولنــا‬\n      ‫إحضــاره ولكنــه يرفــض احلضــور وبســؤال املدعيــة عــن دعواهــا قالــت‬\n‫‪383‬‬\n\f‫إن املدعــى عليــه‪ /‬فهــو زوجــي تزوجنــي مبوجــب العقــد الصحيــح رقــم‬\n‫وتاريــخ ‪1434/1/27‬ه ـ علــى مهــر وقــدره عشــرون ألــف ريــال ولــم‬\n‫يدخــل بــي الدخــول الشــرعي وبعــد زواجــي منــه اكتشــفت أنــه مريــض‬\n‫نفســي وتصرفاتــه غيــر طبيعيــة لــذا أطلــب فســخ نكاحــي منــه هــذه‬\n‫دعــواي وبســؤال والــد املدعــى عليــه ووالدتــه عمــا جــاء يف الدعــوى‬\n‫أجابــا قائلــن إن مــا جــاء يف دعــوى املدعيــة كلــه صحيــح وابننــا املدعــى‬\n‫عليــه كان ســليم ًا ثــم تــزوج وفســخ نكاحــه حلالــة نفســية أصابتــه ثــم‬\n‫بعــد زواجــه باملدعيــة مــرض مرض ـ ًا نفســي ًا وال مانــع لدينــا مــن إجــراء‬\n‫الوجــه الشــرعي هكــذا أجابــا وبســؤالهما عــن الســبب يف عــدم توكيــل‬\n‫ا‬\n‫ابنهمــا لهمــا أو ألحدهمــا أو اســتخراج صــك واليــة علــى قاصــر عق ـ ً‬\n‫أجابــا قائلــن إن ابننــا مــرض نفســي ويرفــض اخلــروج معنــا ألي مــكان‬\n‫بــل يرفــض الذهــاب للمستشــفى هكــذا أجابــا ثــم جــرى االطــاع علــى‬\n‫التقريــر الطبــي الصــادر مــن مستشــفى امللــك فهــد واملترجــم مــن مكتب‬\n‫للترجمــة واملتضمــن مــا نصــه االســم تقريــر طبــي الســيد ‪،‬عمــره ‪29‬‬\n‫ســنة‪ ،‬مريــض‪ /‬ذكــر‪ ،‬أعــزب يعانــي مــن عــدم االســتيقاظ ألكثــر مــن‬\n‫‪ 3‬ســنوات‪ ،‬واضطرابــات نفســية وحضــر مــع والدتــه للمــرة األولــى يف‬\n‫‪1432/6/23‬ه ـ وكان يشــتكي مــن األوهــام‪ ،‬الســلوك الغريــب الــذي‬\n‫للهلوســة الســمعية وصعوبات يف النوم‪ ،‬مت عرضه للطبيب يف مستشــفى‬\n‫جــدة لألمــراض النفســية ومت تشــخيصها علــى أنهــا حالــة انفصــام يف‬\n‫الشــخصية أ‪.‬ه ـ عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبا أن‬\n‫هــذا املــرض يف الــزوج يعــد عيبـ ًا موجبـ ًا للفســخ ونظــر ًا إلــى أن اســتمرار‬\n‫احليــاة الزوجيــة علــى هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح‬\n‫يف الشــريعة مــن املــودة والرحمــة والســكن وتربيــة األوالد والعفــة مــع مــا‬\n\n\n                                                                                       ‫‪384‬‬\n\f      ‫يف ذلــك مــن املضــار النفســية واالجتماعيــة واجلســدية علــى الزوجني وألن‬\n      ‫الشــريعة جــاءت بإزالــة الضــرر فقــد جعلــت للمدعيــة‪ /‬فســخ نكاحهــا‪،‬‬\n      ‫فقالــت‪ :‬فســخت نكاحــي مــن علــى أن أعيــد لــه كامل املهــر وعليه فقد‬\n      ‫ثبــت لــدي فســخ نــكاح املدعيــة‪ /‬مــن املدعــى عليــه‪ /‬وبذلــك حكمــت‬\n      ‫وأفهمــت املدعيــة بأنهــا قــد بانــت مــن زوجهــا بينونــة صغــرى ال حتــل‬\n      ‫لــه إال بعقــد ومهــر جديديــن ثــم ســلم والــد املدعيــة لوالــد املدعــى عليــه‬\n      ‫مبلغــا وقــدره عشــرون ألــف ريــال نقــد ًا وأمــرت برفــع املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيقهــا وأغلقــت اجللســة الســاعة ‪ 02 : 30‬وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                      ‫‪1434/6/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي م القاضــي يف احملكمــة العامــة مبحافظــة‬\n      ‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمة ال ــعامة‬\n      ‫وتاريخ ‪1434/03/15‬هـاملقيدة باحملكمة برقم وتاريخ ‪1434/03/15‬‬\n      ‫ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/11/4‬ه افتتحــت اجللســة الســاعة‬\n      ‫‪01،30‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة رفــق‬\n      ‫خطاب فضيلة رئيسها رقم يف ‪1434/08/22‬هـ وبرفقها القرار رقم يف‬\n      ‫‪1434/08/16‬ه ـ وهــذا نصــه ‪ :‬احلمــد هلل وحــده والصــاة والســام علــى‬\n      ‫رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n      ‫االســتئناف يف منطقــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة برقــم وتاريــخ ‪1434/07/29‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة‬\n      ‫مبحافظــة برقــم وتاريــخ ‪1434/06/26‬ه ـ املتضمــن دعــوى املــرأة مينيــة‬\n\n\n‫‪385‬‬\n\f‫اجلنســية ضــد يف فســخ نكاحهــا مــن املدعــى عليــه وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــرر باألكثريــة اعادتهــا لفضيلــة حاكمهــا ملالحظــة‬\n‫مــا يلــي ‪ -1:‬لــم يصــرح فضيلتــه هــل علــى املدعيــة عــدة أم ال حيــث‬\n‫ذكــرت عــدم الدخــول فهــل حصلــت خلــوة توجــب العــدة ‪ -2 .‬تصحيــح‬\n‫العبــارة ( وعليــه فقــد ثبــت لــدي فســخ نــكاح املدعيــة ‪ .........‬مــن املدعــى‬\n‫عليــه ‪ ..........‬وصحتهــا مــن املدعــى عليــه ‪ ) ........‬وتصحيــح ذلــك يف‬\n‫الصــك وضبطــه وســجله واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم‪ ،،،‬قاضــي اســتئناف ‪ :‬د‪ / .‬قاضــي اســتئناف‬\n‫‪ ( :‬موافــق علــى احلكــم مــع التنبيــه ) ‪ /‬رئيــس الدائــرة ( موافــق علــى مــا‬\n‫ذكــر ولــي إضافــة ) أ‪.‬ه ـ وجوابــا ملــا الحظــه أصحــاب الفضيلــة قضــاة‬\n‫الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار‬\n‫وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة بالقــرار‬\n‫رقــم يف ‪1434/08/16‬ه ـ فبخصــوص املالحظــة األولــى فليــس علــى‬\n‫املدعيــة عــدة لعــدم الدخــول أو اخللــوة وبخصــوص املالحظــة الثانيــة مــن‬\n‫القــرار فقــد أمــرت بتصحيــح العبــارة لتصبــح كالتالــي ‪ :‬فقــد ثبــت لــدي‬\n‫فســخ نــكاح املدعيــة ‪ .......‬مــن املدعــى عليــه ‪ .......‬وأمــرت باحلــاق ذلــك‬\n‫بصــك احلكــم وســجله واعــادة املعاملــة إلــى فضيلــة رئيــس محكمــة‬\n‫االســتئناف مبنطقــة وأغلقــت اجللســة الســاعة ‪02،00‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/04‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف االطــاع‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة وتاريــخ بــدون‬\n\n\n                                                                                       ‫‪386‬‬\n\f      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة‬\n      ‫العامــة وتاريــخ ‪1434/6/26‬ه ـ ‪ ،‬املتضمــن دعــوى املــرأة مينيــة اجلنســية‬\n      ‫ضــد يف فســخ نكاحهــا‪ ،‬وبدراســة الصــك وصــورة ضبطــه ‪ ،‬تقــررت‬\n      ‫املوافقــة علــى احلكــم بعــد اإلجابــة علــى القــرار واهلل املوفــق ‪ .‬وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪387‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":382,"source_page_end":387,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"edb492c80c47e03805ca639e0d5a126f76463bb00682a1a1124bbd09e732a529","normalized_text_hash":"b914c6fee8bd2f83d79f1c232534eed1e239c0ec9bd7d904f70ed1ec88f6af6b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p382-34252367"},{"id":"5e4a24ed-8404-5bd7-9110-a236fb48c239","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ نكاحها بعد الدخول لسوء العشرة ،وإتيانها من الدبر -اإلقرار بإتيان الزوجة من الدبر -إذا تطاوع الزوجان على الوطء من الدبر ،أو أكره الزوج زوجته على ذلك فرق بينهما -احلكم بفسخ النكاح دون عوض .","document_number":"34258948","case_number":"34220075","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/4","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ نكاحها بعد الدخول لسوء العشرة ،وإتيانها من الدبر -اإلقرار بإتيان الزوجة من الدبر -إذا تطاوع الزوجان على الوطء من الدبر ،أو أكره الزوج زوجته على ذلك فرق بينهما -احلكم بفسخ النكاح دون عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/7/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34258948 :‬‬\n                   ‫َر ْق ُم الدعوى‪34220075 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34300037‬تاريخه‪1434/8/17:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ نكاحهــا بعــد الدخــول لســوء العشــرة‬\n‫‪ ،‬وإتيانهــا مــن الدبــر ‪ -‬اإلقــرار بإتيــان الزوجــة مــن الدبــر‪ -‬إذا تطــاوع‬\n‫الزوجــان علــى الــوطء مــن الدبــر‪ ،‬أو أكــره الــزوج زوجتــه علــى ذلــك‬\n                      ‫فــرق بينهمــا ‪ -‬احلكــم بفســخ النــكاح دون عــوض ‪.‬‬\n\n\n\n\n‫قــال يف كشــاف القنــاع (‪« :)81/12‬وإن تطاوعــا أي الزوجــان عليــه‬\n‫أي علــى الــوطء يف الدبــر فــرق بينهمــا أو اكرههــا أي أكــره الرجــل‬\n‫زوجتــه علــى الــوطء يف الدبــر ونهــي عنــه فلــم ينتــه فــرق بينهمــا قــال‬\n      ‫الشــيخ كمــا يفــرق بــن الرجــل الفاجــر وبــن مــن يفجــر بــه» ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة أن املدعــى عليــه تزوجهــا قبــل خمــس ســنوات تقريبــا على‬\n‫مهــر قــدره خمســة عشــر ألــف ريــال مقبوضــة‪ ،‬وأنهــا أجنبــت طف ـاً‪،‬‬\n‫وأن العشــرة ســاءت بينهمــا‪ ،‬وأنهــا تنقــم عليــه يف دينــه وخلقــه‪ ،‬وذلــك‬\n‫أنــه يســئ إليهــا‪ ،‬ويطلــب معاشــرتها بطريــق غيــر شــرعي‪ ،‬ويطالــع‬\n‫املسلســات املخلــة بــاألدب ‪ ،‬وأنــه مقصــر معهــا يف الفــراش‪ ،‬وأنــه‬\n‫ضربهــا قبــل ســتة أشــهر ‪ ،‬وذهــب بهــا إلــى بيــت أهلهــا ولــم تعــد بعدهــا‪،‬‬\n‫وطلبــت فســخ نكاحهــا منــه ‪ ،‬بعــرض دعــوى املدعيــة علــى املدعــى عليــه‬\n\n                                                                                     ‫‪388‬‬\n\f      ‫صــادق علــى الــزواج واملهــر واألوالد‪ ،‬وأنكــر إســاءته للمدعيــة وضربــه‬\n      ‫لهــا‪ ،‬وصــادق علــى األمــور احملرمــة قبــل خمــس ســنوات وقــرر أنــه تــاب‬\n      ‫ولــم يعــد إلــى ذلــك ‪ ،‬كمــا صــادق علــى الذهــاب بهــا لبيــت أهلهــا‪،‬‬\n      ‫وأنــه مقصــر معهــا يف الفــراش وأنــه تعالــج مــن ذلــك مؤخــرا ‪ ،‬جــرى‬\n      ‫التحكيــم بــن الزوجــن فاختلــف احلكمــان حيــث أن حكــم الزوجــة‬\n      ‫يــرى الفرقــة بــدون عــوض ويــرى حكــم الــزوج اجلمــع بــن الزوجــن ‪،‬‬\n      ‫ورأت جلنــة الصلــح باحملكمــة الفرقــة بــدون عــوض وذلــك لوقــوع خلــل‬\n      ‫يف مقصــود النــكاح مــن األلفــة وحســن العشــرة مــن ضــرب وغيــره‪،‬‬\n      ‫وكــون الــزوج يأتــي زوجتــه مــن الدبــر باإلكــراه واعتــرف أمــام اللجنــة‬\n      ‫بفعلــه احملــرم وأنــه تــاب مــن هــذه الفعلة ‪ -‬جرى وعــظ الطرفني ومحاولة‬\n      ‫الصلــح بينهمــا وبيــان مــا لــكل واحــد منهمــا علــى اآلخــر فأصــر كلُّ‬\n      ‫واحــدٍ منهمــا علــى رأيــه ‪ ،‬ملــا قــرره أعضــاء جلنــة الصلــح ‪ ،‬ومــا تبــن مــن‬\n      ‫عظــم الشــقاق بــن الطرفــن وانعــدام مقصــود الشــارع مــن بقــاء الزوجيــة‬\n      ‫بينهمــا ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه‬\n      ‫دون عــوض ‪ ،‬بعــرض احلكــم علــى الطرفــن قنعــت املدعيــة ولــم يقنــع‬\n      ‫املدعــى عليــه ‪ ،‬جــرى إفهــام املــرأة أال تتــزوج حتــى يكتســب احلكــم‬\n      ‫القطعيــة وأن عليهــا أن تعتــد حســب حالهــا ‪ ،‬بعــد رفــع احلكــم حملكمــة‬\n                                                 ‫االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 34220075‬وتاريــخ ‪ 1434/05/13‬ه ـ املقيــدة‬\n\n‫‪389‬‬\n\f‫باحملكمــة برقــم ‪ 341171397‬وتاريــخ ‪ 1434/05/13‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/05/28‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬‬\n‫صباحــا وفيهــا حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬حلضورهــا زوجهــا املدعــى عليــه (‪ )........‬يـم ــني اجلنســية‬\n‫إقامــة رقــم (‪ )........‬وبســؤالها عــن دعواهــا ادعــت قائلــه تزوجنــي املدعــى‬\n‫عليــه قبــل ســبع ســنوات تقريبــا علــى مهــر قــدره خمســة عشــر ألــف ريــال‬\n‫مقبوضــة واجنبــت لــه طفــا اســمه (‪ )........‬عمــره خمــس ســنوات وقــد‬\n‫ســاءت العشــرة بيننــا ولــم نكــن علــى وفــاق وأننــي انقــم عليــه يف دينــه‬\n‫وخلقــه فهــو يســئ إلــى ويســئ معاشــرتي ويطلبنــي بطــرق غيــر شــرعيه‬\n‫ويطالــع املسلســات املخلــة بــاألدب كمــا انــه مقصــر معــي يف الفــراش‬\n‫وقــد ضربنــي قبــل ســتة أشــهر وذهــب بــي إلــى بيــت أهلــي وحتــى اآلن لــم‬\n‫أعــد لــذا أطلــب فســخ نكاحــي منــه هــذه دعــواي وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أجــاب بقولــه ما ذكرته املدعية مــن الزواج وتاريخه واملهر‬\n‫وقــدره وقبضــه واألوالد فصحيــح غيــر أنــي ال أســئ إليهــا وال أضربهــا‬\n‫وأمــا مــا يتعلــق باألمــور احملرمــة فإننــي قــد حاولــت ذلــك ومتكنــت منــه‬\n‫قبــل خمــس ســنوات وقــد تبــت ولــم اعــد مــن خمــس ســنوات إلــى ذلــك‬\n‫ولــم اضربهــا وقــد ذهبــت بهــا إلــى أهلهــا وقلــت لهــم دعوهــا عندكــم‬\n‫تتربــى ولــم أصــرح بطالقــي لهــا كمــا أننــي كنــت مقصــر معهــا يف‬\n‫الفــراش وقــد تعاجلــت مــن ذلــك مؤخــرا هكــذا أجــاب وعنــد وصــول‬\n‫القضيــة لهــذا احلــد قــررت بعــث املعاملــة إلــى مكتــب الصلــح لالجتمــاع‬\n‫بالطرفــن والنظــر يف شــانهم وحتديــد مــا يلــزم مــن فســخ مجانــي أو‬\n‫بعــوض أو اصــاح بينهمــا وجــرى حتديــد موعــد لــدى مكتــب الصلــح‬\n‫يف يــوم االحــد املوافق‪1434/06/18‬ه ـ علــى أن يكــون املوعــد لدينــا يف‬\n\n\n                                                                                     ‫‪390‬‬\n\f      ‫يــوم األربعــاء املوافق‪1434/06/21‬ه ـ الســاعة العاشــرة صباحا وختمت‬\n      ‫اجللســة الســاعة احلاديــة العشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 34220075‬وتاريــخ ‪ 1434/05/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341171397‬وتاريــخ ‪ 1434/05/13‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق‪ 1434/07/03‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n      ‫وفيهــا حضــر الطرفــان وكان قــد وردنــا قــرار مكتــب الصلــح رقــم‬\n      ‫‪/251‬ص وتاريخ‪1434/06/18‬ه ـ املتضمــن أنــه بنــاء علــى القــرار‬\n      ‫‪/250‬ص وتاريــخ ‪1434/16/18‬ه ـ املتضمــن اختــاف احلكمــان حيــث‬\n      ‫أن حكــم الزوجــة يــرى الفرقــة بــدون عــوض ويــرى حكــم الــزوج اجلمــع‬\n      ‫بــن الزوجــن فبنــاء عليــه تــرى اللجنــة والــرأي لفضيلتكــم الفرقــة‬\n      ‫بــدون عــوض وذلــك لوقــوع خلــل يف مقصــود النــكاح مــن األلفــة وحســن‬\n      ‫العشــرة مــن ضــرب وغيــره وأن الــزوج يأتــي زوجــة مــن الدبــر باإلكــراه‬\n      ‫وقــد تكــرر ذلــك ثــاث مــرات واعتــرف أمــام اللجنــة بفعلــه احملــرم وقــد‬\n      ‫تــاب مــن هــذه الفعلــة املوقــع مــن أعضــاء جلنــة الصلــح ‪ .......‬و‪ .......‬و‪.........‬‬\n      ‫و‪ .........‬و‪ ........‬ويف هــذه اجللســة جــرى وعــظ الطرفــن ومحاولــة الصلــح‬\n      ‫بينهمــا وبيــان مــا لــكل واحــد منهمــا علــى اآلخــر فأصــر كل واحــد‬\n      ‫منهمــا علــى رأيــه‪ ،‬وبنــاء علــى مــا تقــدم بعــد ســماع الدعــوى واإلجابــة‬\n      ‫وحيــث صــادق املدعــى عليــه علــى دعــوى املدعيــة مبــا يتعلــق بضعفــه‬\n      ‫ومــا يقــوم بــه مــن أعمــال تنــايف الفطــرة الســليمة اكثــر مــن مــره وملــا‬\n      ‫قــرره اعضــاء جلنــة الصلــح أعــاه ولــم نــص عليــه يف الكشــاف ( وإن‬\n\n\n‫‪391‬‬\n\f‫تطاوعــا أي الزوجــان عليــه أي علــى الــوطء يف الدبــر فــرق بينهمــا أو‬\n‫اكرههــا أي اكــره الرجــل زوجتــه علــى الــوطء يف الدبــر ونهــي عنــه‬\n‫فلــم ينتــه فــرق بينهمــا قــال الشــيخ كمــا يفــرق بــن الرجــل الفاجــر وبــن‬\n‫مــن يفجــر بــه ) ج‪12‬ص‪ 81‬وملــا تبــن مــن عظــم الشــقاق بــن الطرفــن‬\n‫وانعــدام مقصــود الشــارع مــن بقــاء الزوجيــة بينهمــا لذلــك كلــه فقــد‬\n‫حكمــت فســخ نــكاح املــرأة ‪ ........‬مــن زوجهــا ‪ ..........‬دون عــوض‬\n‫وبعرضــه عليهمــا قنعــت املدعيــة ولــم يقنــع املدعــى عليــه فجــرى افهامــه‬\n‫بــأن لــه حــق االعتــراض علــى احلكــم بطلــب االســتئناف وذلــك خــال‬\n‫ثالثــون يومــا مــن تاريــخ مــن تاريــخ يــوم غــد الثالثــاء وذلــك بتقــدمي الئحــة‬\n‫اعتراضيــة وإن مضــت املــدة دون تقــدمي الئحــة اعتراضيــه ســقط حقــه‬\n‫باالعتــراض بطلــب االســتئناف واكتســب احلكــم الصفــة القطعيــة وأن‬\n‫عليــه مراجعــة احملكمــة غــدا الســتالم احلكــم ثــم جــرى إفهــام املــرأة‬\n‫أال تتــزوج حتــى يكتســب احلكــم القطعيــة وان عليهــا ان تعتــد حســب‬\n‫حالهــا وختمــت اجللســة الســاعة العاشــرة والنصــف صباحــا وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪1434/7/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬ال ــقاضي يف احملكمــة العامـ ــة‬\n‫بالطائــف ففــي ي ــوم االثنــن امل ــوافق ‪1434/09/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة والربــع صباحــا وكان قــد وردنــا قــرار محكمــة‬\n‫االســتئناف الدائــرة الثالثــة ‪/‬لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫مبكــة املكرمــة برقــم ‪ 34300037‬وتاريــخ ‪1434/08/17‬ه ـ املتضمــن‬\n‫املوافقــة علــى احلكــم بفســخ النــكاح مــع مالحظــة التنبيــه املرفــق‬\n‫أعضــاء الدائــرة قاضــي اســتئناف ‪ ..............‬ختــم وتوقيــع قاضــي‬\n\n\n                                                                                          ‫‪392‬‬\n\f      ‫اســتئناف ‪ ............‬موقــع علــى األصــل وموافــق علــى احلكــم ومجــاز‬\n      ‫قاضــي اســتئناف رئيــس الدائــرة ‪ .............‬ختــم وتوقيــع وبذلــك يكــون‬\n      ‫احلكــم اكتســب القطعيــة لــذا جــرى إثباتــه حتــى ال يخفــى وأمــرت‬\n      ‫بإحلــاق التهميــش علــى ســجله وختمــت اجللســة الســاعة العاشــرة‬\n      ‫والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/7‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف املكلــف برقــم ‪ 341171397‬وتاريــخ ‪1434/8/6‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪ )........‬القاضــي‬\n      ‫باحملكمــة العامــة بالطائــف برقــم ‪ 34258948‬وتاريــخ ‪1434/7/4‬ه ـ‬\n      ‫‪ ،‬املتضمــن دعــوى املــرأة (‪ )........‬ضــد زوجهــا (‪ )........‬ي ــمني اجلنســية يف‬\n      ‫فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة ‪ ،‬تقــرر املوافقــة علــى احلكــم بفســخ النــكاح‬\n      ‫‪ ،‬مــع مالحظــة التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪393‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":388,"source_page_end":393,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"74e74a3435f67a197b5da55a2a0372e40df3f5a7bf149f7cd2ba4de2e65666a9","normalized_text_hash":"ced9ff58288fe60e7a899cb87d513c07c7cdce52dddc6ae728b279cf59361d9c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p388-34258948"},{"id":"10e48d19-255d-5f67-942c-001c2236a3b1","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -املطالبة بفسخ نكاح لسوء العشرة والهجر وعدم النفقة -موافقة الزوج على الفسخ بغير عوض مالي بشرط حضانة األوالد له ورد كامل مصروفات الزواج -صدور صك سابق بحضانة األوالد -احلكم بفسخ النكاح من غير عوض مالي .","document_number":"34270704","case_number":"34297578","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"فسخ نكاح -املطالبة بفسخ نكاح لسوء العشرة والهجر وعدم النفقة -موافقة الزوج على الفسخ بغير عوض مالي بشرط حضانة األوالد له ورد كامل مصروفات الزواج -صدور صك سابق بحضانة األوالد -احلكم بفسخ النكاح من غير عوض مالي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34270704 :‬‬\n                   ‫َر ْق ُم الدعوى‪34297578 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34320755‬تاريخه‪1434/9/16:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬املطالبــة بفســخ نــكاح لســوء العشــرة والهجــر وعــدم‬\n‫النفقــة ‪ -‬موافقــة الــزوج علــى الفســخ بغيــر عــوض مالــي بشــرط‬\n‫حضانــة األوالد لــه ورد كامــل مصروفــات الــزواج ‪ -‬صــدور صــك ســابق‬\n ‫بحضانــة األوالد ‪ -‬احلكــم بفســخ النــكاح مــن غيــر عــوض مالــي ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قول النبي صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n                                                       ‫‪ -2‬قاعدة ( الضرر يزال)‬\n‫‪ -3‬مــا قــرره ابــن تيميــة وغيــره مــن أهــل العلــم (أنــه يجــوز إلــزام الــزوج‬\n‫بالفســخ واخللــع عنــد عــدم تــاؤم احلــال بــن الزوجــن وبــه الــزم بعــض‬\n                                           ‫حــكام الشــام) الفــروع البــن مفلــح ‪.‬‬\n‫‪ -4‬قــال ابــن العربــي‪( :‬متــى حصــل خلــل مبقصــود النــكاح مــن عــدم‬\n‫األلفــة وحســن املعاشــرة وفقــد اإلتفــاق والتآلــف وحســن التعاشــر ســواء‬\n‫كان مــن قبــل الزوجــن معــا أو مــن أحدهمــا لــم يكــن لبقــاء العقــد‬\n                                 ‫وجــه وفــرق بينهمــا بعــوض أو بدونــه) ‪.‬‬\n\n\n\n\n‫أقامــت امــرأة دعــوى تطالــب زوجهــا فســخ نكاحهــا ألنــه ســيء العشــرة‬\n‫وال ينفــق عليهــا وال علــى أوالدهــا منــه وأنهــا قــد انفصلــت عنــه منــذ‬\n\n                                                                                        ‫‪394‬‬\n\f      ‫إحــدى عشــرة ســنه ‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعيــة‬\n      ‫ووافــق علــى طلبهــا فســخ النــكاح مــن غيــر عــوض بشــرط تســليمه بناتــه‬\n      ‫التــي حتــت يــد املدعيــة وأن تــرد لــه كامــل مصروفــات الــزواج ‪ ،‬بعــرض‬\n      ‫ذلــك علــى املدعيــة قالــت‪ :‬املدعــى عليــه يريــد تعليقــي وهــذا ال يجــوز‬\n      ‫شــرعا وال أوافــق علــى تســليمه البنــات وموضــوع تســليم البنــات ســبق‬\n      ‫أن صــدر بــه صــك مكتســب للقطعيــة ‪ ،‬اطلعــت احملكمــة علــى صــك‬\n      ‫احلضانــة املذكــور ‪ ،‬وألن املدعــى عليــه قــرر موافقتــه علــى فســخ نــكاح‬\n      ‫املدعيــة مــن غيــر عــوض مالــي وألنــه تعــذرت العشــرة بينهمــا وطــال أمــد‬\n      ‫تعليــق الزوجــة مــن غيــر مصلحــة ولقــول الرســول صلــى اهلل عليــه وســلم‬\n      ‫(ال ضــرر وال ضــرار) وملــا أجمــع عليــه أهــل العلــم مــن أن الضــرر يــزال‬\n      ‫الســيما يف عقــد النــكاح الــذي مقصــوده احملبــة واملــودة لــذا قضــت‬\n      ‫احملكمــة بفســخ نــكاح املدعيــة مــن عصمــة زوجهــا مــن غيــر عــوض‬\n      ‫مالــي وأفهمتهــا بــأن عليهــا العــدة الشــرعية ‪ ،‬اعتــرض املدعــى عليــه ‪،‬‬\n                                      ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n      ‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة جــدة برقــم وتاريــخ ‪ 1434/06/27‬ه ـ املقيــدة باحملكمــة‬\n      ‫وتاريــخ ‪ 1434/06/27‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/07/17‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )09 : 30‬وفيهــا حضــرت (‪ )........‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬واملعــرف بهــا مــن قبــل‬\n      ‫أخيهــا (‪ ،)........‬واملدعــى عليــه (‪ )........‬فادعــت ضــد احلاضــر معهــا يف‬\n\n‫‪395‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":394,"source_page_end":395,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"033b05719dafa8658887d5ccffb22b16c7c2f20d411d9641930a6d9d4dd2c7e7","normalized_text_hash":"56dc776450696342f2692eb19b6279926c402f0e379124f6263665a4294fe224","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p394-34270704"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

